import sys, pathlib, re
bad = []
for p in pathlib.Path('.').rglob('*.md'):
    if '.git' in p.parts:
        continue
    for link in re.findall(r'\]\(([^)]+)\)', p.read_text(encoding='utf-8', errors='ignore')):
        if link.startswith(('http', '#', 'mailto', '<')):
            continue
        target = (p.parent / link.split('#')[0])
        if not target.exists():
            bad.append(f'{p} -> {link}')
print('\n'.join(bad))
print(f'links checked, {len(bad)} broken')
sys.exit(2 if bad else 0)

import sys, pathlib
bad = []
for p in pathlib.Path('.').rglob('*.md'):
    if '.git' in p.parts:
        continue
    try:
        p.read_text(encoding='utf-8')
    except UnicodeDecodeError:
        bad.append(str(p))
print('\n'.join(bad))
print(f'files checked, {len(bad)} not-utf8')
sys.exit(2 if bad else 0)
